package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Arrays;
import java.util.Locale;
import java.util.TreeSet;
import java.util.regex.Pattern;

/** A claim's values once validated. {@code date} is null when none was given (the sheet's today applies). {@code corrects} is the number of
 *  the claim a correction corrects (null when none was given). {@code by} is who gives them. {@code ref} is its external reference,
 *  surrounding spaces removed (null when none, or a blank one, was given). {@code tags} are its tags as stored (see #tags; null when none). */
public record ClaimValues(BigDecimal amount, LocalDate date, String note, String corrects, String by, String ref, String tags) {
    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,15}(\\.\\d{1,2})?");

    /** The request's values by the claim form's rules (see ValidateClaim). */
    public static ClaimValues from(ClaimRequest request) throws InvalidClaimException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals");
        }
        String date = request.date() == null ? "" : request.date().trim();
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("The date must be yyyy-MM-dd");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        String corrects = request.corrects() == null ? "" : request.corrects().trim();
        String ref = request.ref() == null ? "" : request.ref().trim();
        return new ClaimValues(new BigDecimal(amount).setScale(2), parsed, note, corrects.isEmpty() ? null : corrects,
                request.by() == null ? "" : request.by().trim(), ref.isEmpty() ? null : ref,
                tags(request.tags()));
    }

    /** Comma separated tags as stored: each trimmed and in lower case, blanks and repeats dropped, sorted, joined by
     *  commas; null when none is left. */
    public static String tags(String typed) throws InvalidClaimException {
        if (typed == null) {
            return null;
        }
        String joined = String.join(",", new TreeSet<>(Arrays.stream(typed.split(",")).map((t) -> t.trim().toLowerCase(Locale.ROOT))
                .filter((t) -> !t.isEmpty()).toList()));
        if (joined.length() > 2000) {
            throw new InvalidClaimException("The tags are too long");
        }
        return joined.isEmpty() ? null : joined;
    }

    /** The reference as compared: without regard to case. */
    public static String refKey(String ref) {
        return ref == null ? null : ref.toLowerCase(Locale.ROOT);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim to the person; a claim given no date is dated the sheet's entry date, else its today. A claim whose due-by falls inside
 *  a closed period, or dated after the person's retirement date, is refused, as is a
 *  negative amount that does not correct a SETTLED claim of the person (see Corrections). Its due-by is fixed here: its
 *  terms-th business day after its date (see ClaimRules.dueBy). A claim whose due-by falls inside a soft-closed period is
 *  marked a late entry. Its status log starts with its DRAFT line (see ClaimLog). */
public class AddClaim {
    public void add(@Val Person person, @Val ClaimValues values, ClaimRepository claims,
            PeriodRepository periods, SettingRepository settings, HolidayRepository holidays, ClaimLog log, Out<Claim> claim) throws InvalidClaimException {
        ClaimRules.Checked checked = ClaimRules.check(person, values, settings, periods, claims, holidays);
        LocalDate date = checked.date();
        Claim added = claims.add(person.sheetId(), person.id(), values.amount(), date, values.note(), checked.corrects(),
                values.ref(), values.tags(), checked.dueBy(), checked.terms());
        log.write(added, values.by());
        if (periods.softClosedOn(added.sheetId(), checked.dueBy())) {
            claims.markLateEntry(added);
        }
        claim.set(added);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_ADDED to the audit file (with ref=<reference> then tags=<tags, sorted, comma separated> at its end when the claim has them) once the claim is stored, then LATE_ENTRY for a late entry (see AddClaim). Then writes the
 * figures the change moved (see Rollup). */
public class RecordClaimAdded {
    public void record(@Val Claim claim, @Val Person person, @Val ClaimValues values, @Val RollupBefore before, ClaimRepository claims, Rollup rollup, Audit audit) {
        audit.record("CLAIM_ADDED sheet=" + claim.sheetId() + " by=" + values.by() + " person=" + person.name()
                + " amount=" + claim.amount().toPlainString() + " date=" + claim.date()
                + (claim.ref() == null ? "" : " ref=" + claim.ref())
                + (claim.tags() == null ? "" : " tags=" + claim.tags()));
        if (claims.lateEntry(claim.sheetId(), claim.id())) {
            audit.record("LATE_ENTRY sheet=" + claim.sheetId() + " by=" + values.by() + " person=" + person.name()
                    + " amount=" + claim.amount().toPlainString() + " date=" + claim.date());
        }
        rollup.record(claim.sheetId(), values.by(), before);
    }
}
